sed -i 's/val exportLauncher = androidx.activity.compose.rememberLauncherForActivityResult(/val exportLauncher = androidx.activity.compose.rememberLauncherForActivityResult(\n                contract = androidx.activity.result.contract.ActivityResultContracts.CreateDocument("text\/csv")\n            ) { uri ->\n                uri?.let { viewModel.exportDataToCsv(context, it) }\n            }\n            val backupLauncher = androidx.activity.compose.rememberLauncherForActivityResult(\n                contract = androidx.activity.result.contract.ActivityResultContracts.CreateDocument("application\/json")\n            ) { uri ->\n                uri?.let { viewModel.exportBackup(context, it) }\n            }\n            val importLauncher = androidx.activity.compose.rememberLauncherForActivityResult(\n                contract = androidx.activity.result.contract.ActivityResultContracts.OpenDocument()\n            ) { uri ->\n                uri?.let { viewModel.importBackup(context, it) }\n            }/' app/src/main/java/com/example/ui/AnalyticsScreen.kt
